import javax.xml.parsers.DocumentBuilderFactory;

import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.QueryResults;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.query.impl.IteratingTupleQueryResult;
import org.eclipse.rdf4j.query.resultio.TupleQueryResultWriter;
import org.junit.jupiter.api.Test;
import org.xml.sax.SAXException;
import org.xml.sax.SAXParseException;
import org.xml.sax.helpers.DefaultHandler;

class ODSStylesNamespaceIssueTest {

	@Test
	void explicitlyStartedWriterProducesNamespaceWellFormedXmlEntries() throws Exception {
		ByteArrayOutputStream out = new ByteArrayOutputStream();
		TupleQueryResultWriter writer = new SPARQLResultsODSWriterFactory().getWriter(out);
		writer.startDocument();
		TupleQueryResult emptyResult = new IteratingTupleQueryResult(List.of("name"), List.<BindingSet>of());
		QueryResults.report(emptyResult, writer);

		assertEveryXmlEntryIsNamespaceWellFormed(out.toByteArray());
	}

	private void assertEveryXmlEntryIsNamespaceWellFormed(byte[] archive) throws Exception {
		Set<String> xmlEntries = new HashSet<>();
		List<String> malformedXml = new ArrayList<>();
		DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
		factory.setNamespaceAware(true);
		var builder = factory.newDocumentBuilder();
		builder.setErrorHandler(new DefaultHandler() {
			@Override
			public void fatalError(SAXParseException exception) throws SAXException {
				throw exception;
			}
		});

		try (ZipInputStream zip = new ZipInputStream(new ByteArrayInputStream(archive))) {
			for (ZipEntry entry; (entry = zip.getNextEntry()) != null;) {
				if (entry.getName().endsWith(".xml")) {
					xmlEntries.add(entry.getName());
					try {
						builder.parse(new ByteArrayInputStream(zip.readAllBytes()));
					} catch (SAXException exception) {
						String location = exception instanceof SAXParseException parseException
								? " at line " + parseException.getLineNumber() + ", column "
										+ parseException.getColumnNumber()
								: "";
						malformedXml.add(entry.getName() + location + ": " + exception.getMessage());
					}
				}
				zip.closeEntry();
			}
		}

		assertEquals(Set.of("styles.xml", "meta.xml", "META-INF/manifest.xml", "content.xml"), xmlEntries);
		assertEquals(List.of(), malformedXml, "Every XML ZIP entry must be namespace-well-formed");
	}
}
